#!/usr/bin/env python3
"""
Temporary memory test (removed again): runs the real Minecraft client (Linux build, software OpenGL) with a
500 MB heap in a singleplayer world, so that the client and the integrated server share the heap like on a
phone, and reports for each JVM flag set whether it ran out of memory and how much heap stayed in use.

usage: memtest.py <version> <seconds in the world> <set>=<jvm flags> ...
"""
import json, os, re, shutil, signal, subprocess, sys, time, urllib.request, zipfile

VERSION, PLAY_SECONDS = sys.argv[1], int(sys.argv[2])
SETS = [a.split("=", 1) for a in sys.argv[3:]]
WORK = os.path.abspath("mc")
LIBS, NATIVES, ASSETS = (os.path.join(WORK, d) for d in ("libraries", "natives", "assets"))


def get(url, path=None):
    for attempt in range(4):
        try:
            data = urllib.request.urlopen(url, timeout=120).read()
            break
        except Exception:
            if attempt == 3:
                raise
            time.sleep(3)
    if path:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        open(path, "wb").write(data)
    return data


def allowed(rules):
    if not rules:
        return True
    ok = False
    for rule in rules:
        os_rule = rule.get("os", {})
        if "features" in rule:
            continue
        if not os_rule or os_rule.get("name", "linux") == "linux" and os_rule.get("arch", "x86_64") in ("x86_64", "x64", "amd64"):
            ok = rule["action"] == "allow"
    return ok


def notice(title, msg):
    print(msg)
    print(f"::notice title={title}::" + msg.replace("%", "%25").replace("\n", "%0A"))


manifest = json.loads(get("https://piston-meta.mojang.com/mc/game/version_manifest_v2.json"))
meta = json.loads(get(next(v["url"] for v in manifest["versions"] if v["id"] == VERSION)))
java_major = meta.get("javaVersion", {}).get("majorVersion", 8)

# --- client, libraries, natives, asset index -------------------------------------------------------------
classpath = []
os.makedirs(NATIVES, exist_ok=True)
for lib in meta["libraries"]:
    if not allowed(lib.get("rules")):
        continue
    downloads = lib.get("downloads", {})
    artifact = downloads.get("artifact")
    if artifact:
        path = os.path.join(LIBS, artifact["path"])
        get(artifact["url"], path)
        classpath.append(path)  # LWJGL 3 extracts its natives from natives-* jars on the classpath
    natives = lib.get("natives", {})
    if "linux" in natives:  # old style (LWJGL 2): extract into the natives directory
        info = downloads["classifiers"][natives["linux"].replace("${arch}", "64")]
        path = os.path.join(LIBS, info["path"])
        get(info["url"], path)
        with zipfile.ZipFile(path) as z:
            for name in z.namelist():
                if not name.startswith("META-INF") and not name.endswith("/"):
                    open(os.path.join(NATIVES, os.path.basename(name)), "wb").write(z.read(name))
client_jar = os.path.join(WORK, "versions", VERSION, VERSION + ".jar")
get(meta["downloads"]["client"]["url"], client_jar)
classpath.append(client_jar)
asset_index = meta["assetIndex"]
index = json.loads(get(asset_index["url"], os.path.join(ASSETS, "indexes", asset_index["id"] + ".json")))
# Every asset except the sound files (fonts like unifont are needed to start)
from concurrent.futures import ThreadPoolExecutor
wanted = sorted({obj["hash"] for name, obj in index["objects"].items() if not name.endswith(".ogg")})
with ThreadPoolExecutor(16) as pool:
    list(pool.map(lambda h: get(f"https://resources.download.minecraft.net/{h[:2]}/{h}",
                                os.path.join(ASSETS, "objects", h[:2], h)), wanted))
print(f"{len(wanted)} assets downloaded")

def java_for(major):
    home = os.environ.get(f"JAVA_HOME_{major}_X64")
    return (os.path.join(home, "bin", "java"), os.path.join(home, "bin", "jcmd")) if home else ("java", "jcmd")


# --- a world, generated by the dedicated server of the same version -----------------------------------------
server_dir = os.path.join(WORK, "server")
os.makedirs(server_dir, exist_ok=True)
get(meta["downloads"]["server"]["url"], os.path.join(server_dir, "server.jar"))
open(os.path.join(server_dir, "eula.txt"), "w").write("eula=true\n")
open(os.path.join(server_dir, "server.properties"), "w").write(
    "level-name=World\nlevel-seed=4815162342\nview-distance=4\nsimulation-distance=5\nonline-mode=false\nspawn-protection=0\n")
started = time.time()
server = subprocess.Popen([java_for(java_major)[0], "-Xmx2G", "-jar", "server.jar", "--nogui"], cwd=server_dir,
                          stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
for line in server.stdout:
    if "Done (" in line:
        break
server.stdin.write("stop\n")
server.stdin.flush()
server.wait(timeout=300)
print(f"world generated in {time.time() - started:.0f}s")

# --- the client, once per flag set -------------------------------------------------------------------------
OPTIONS = open(sys.argv[0].replace("memtest.py", "options.txt")).read()
results = []
for spec, flags in SETS:
    parts = spec.split("@")
    set_name, heap = parts[0], parts[1] if len(parts) > 1 and parts[1] else "500"
    run_major = int(parts[2]) if len(parts) > 2 else java_major
    java_bin, jcmd_bin = java_for(run_major)
    set_name = f"{set_name}({heap}M,J{run_major})"
    game_dir = os.path.join(WORK, "game-" + parts[0])
    shutil.rmtree(game_dir, ignore_errors=True)
    shutil.copytree(os.path.join(server_dir, "World"), os.path.join(game_dir, "saves", "World"))
    open(os.path.join(game_dir, "options.txt"), "w").write(OPTIONS)
    gc_log = os.path.join(WORK, f"gc-{parts[0]}.log")
    log_flags = [f"-Xlog:gc:file={gc_log}:uptime"] if run_major >= 9 else ["-XX:+PrintGCDetails", f"-Xloggc:{gc_log}"]
    cmd = ([java_bin, f"-Xms{heap}M", f"-Xmx{heap}M"] + flags.replace("_", " ").split() + log_flags +
           [f"-Djava.library.path={NATIVES}", "-cp", ":".join(classpath), meta["mainClass"],
            "--username", "Tester", "--version", VERSION, "--gameDir", game_dir, "--assetsDir", ASSETS,
            "--assetIndex", asset_index["id"], "--uuid", "00000000000000000000000000000001", "--accessToken", "0",
            "--userType", "msa", "--versionType", "release", "--width", "854", "--height", "480",
            "--quickPlaySingleplayer", "World"])
    out_path = os.path.join(WORK, f"client-{parts[0]}.log")
    out = open(out_path, "w")
    proc = subprocess.Popen(cmd, cwd=game_dir, stdout=out, stderr=subprocess.STDOUT, preexec_fn=os.setsid)
    start, joined_at, deadline, histogram = time.time(), None, time.time() + 600, None
    while proc.poll() is None and time.time() < deadline:
        time.sleep(5)
        text = open(out_path, errors="replace").read()
        if histogram is None and os.path.exists(gc_log) and "Pause Full" in open(gc_log, errors="replace").read():
            try:
                h = subprocess.run([jcmd_bin, str(proc.pid), "GC.class_histogram"], capture_output=True, text=True, timeout=60).stdout
                histogram = "\n".join("      " + l.strip()[:120] for l in h.splitlines()[2:14])
            except Exception as e:
                histogram = f"      (histogram failed: {e})"
        if joined_at is None and re.search(r"Tester joined the game|logged in with entity id", text):
            joined_at = time.time()
            deadline = joined_at + PLAY_SECONDS
    alive = proc.poll() is None
    if alive:
        os.killpg(proc.pid, signal.SIGTERM)
        try:
            proc.wait(timeout=60)
        except subprocess.TimeoutExpired:
            os.killpg(proc.pid, signal.SIGKILL)
    out.close()
    text = open(out_path, errors="replace").read()
    oom = "OutOfMemoryError" in text or any("OutOfMemory" in open(os.path.join(dp, f), errors="replace").read()
                                            for dp, _, fs in os.walk(os.path.join(game_dir, "crash-reports")) for f in fs)
    # GC log: "... GC(12) Pause Young (Normal) (G1 Evacuation Pause) 312M->134M(500M) 12.345ms"
    after, pauses, full, full_causes, startup_after = [], [], 0, {}, []
    for line in open(gc_log, errors="replace") if os.path.exists(gc_log) else []:
        m = re.search(r"\[([\d.]+)s\].*Pause (\w+)(.*?)(\d+)M->(\d+)M\((\d+)M\)\s+([\d.]+)ms", line)
        if not m:
            continue
        t, kind, detail, before, now, size, ms = m.groups()
        if joined_at and float(t) >= joined_at - start + 10:  # in the world, after the first 10 seconds
            after.append(int(now))
        else:
            startup_after.append(int(now))
        pauses.append(float(ms))
        if kind == "Full":
            full += 1
            cause = detail.strip().strip("()") or "?"
            full_causes[cause] = full_causes.get(cause, 0) + 1
    crashed = not alive and not oom
    results.append(
        f"{set_name:9s} {'JOINED' if joined_at else 'no join'}{f' in {joined_at - start:.0f}s' if joined_at else ''}"
        f"{' OUT OF MEMORY' if oom else ''}{' (process ended early)' if crashed else ''} | "
        f"heap in use after GC in the world: max {max(after) if after else '-'} MB, median "
        f"{sorted(after)[len(after) // 2] if after else '-'} MB, before the world max {max(startup_after) if startup_after else '-'} MB | "
        f"{len(pauses)} GCs ({full} full: {', '.join(f'{k} x{v}' for k, v in full_causes.items()) or '-'}), "
        f"longest pause {max(pauses) if pauses else 0:.0f} ms, total {sum(pauses) / 1000:.1f} s")
    if histogram:
        results.append("    heap at the first full GC:\n" + histogram)
    tail = [l for l in text.splitlines() if re.search(r"OutOfMemory|FATAL", l)][-3:]
    if tail:
        results.append("    " + "\n    ".join(t[:220] for t in tail))
notice(f"Minecraft {VERSION} (needs Java {java_major})", "\n".join(results))
